#include "../Source/PluginProcessor.h"
#include <iostream>
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI init;if(argc<3)return 2;juce::AudioFormatManager fm;fm.registerBasicFormats();auto reader=std::unique_ptr<juce::AudioFormatReader>(fm.createReaderFor(juce::File(argv[1])));if(!reader)return 3;auto p=std::make_unique<PrismProcessor>();double sr=reader->sampleRate;int frames=int(std::min<juce::int64>(reader->lengthInSamples,juce::int64(sr*8)));juce::AudioBuffer<float> source(2,frames);reader->read(&source,0,frames,0,true,true);juce::AudioBuffer<float> b(2,256);juce::MidiBuffer midi;double total=0;for(int preset=0;preset<16;++preset){p->setCurrentProgram(preset);p->prepareToPlay(sr,256);double e=0;float peak=0;for(int offset=0;offset<frames;offset+=256){b.clear();int n=std::min(256,frames-offset);for(int c=0;c<2;++c)b.copyFrom(c,0,source,c,offset,n);p->processBlock(b,midi);for(int c=0;c<2;++c)for(int i=0;i<n;++i){float x=b.getSample(c,i);if(!std::isfinite(x)||std::abs(x)>8)return 4;e+=x*x;peak=std::max(peak,std::abs(x));}}std::cout<<preset<<" peak="<<peak<<" rms="<<std::sqrt(e/(frames*2))<<'\n';total+=e;}std::cout<<"PASS real recording processed through all 16 factory starting points: "<<juce::File(argv[1]).getFileName()<<" at "<<sr<<" Hz; energy="<<total<<"; analysis only, not a listening judgement.\n";return total>0?0:5;}
